-- Products (primary shelf = first subcategory)

insert into public.products (category_id, brand_id, name, slug, description, unit_label, mrp, price, tax_rate, images, tags, is_veg, orderable, image_credit)
select c.id, b.id, v.name, v.slug, v.description, v.unit_label, v.mrp, v.price, v.tax_rate, v.images, v.tags, v.is_veg, v.orderable, v.image_credit from (values
  ('atta-rice-dal-dal', null, 'Toor Dal', 'toor-dal', 'Split pigeon peas for everyday sambar and dal tadka. Rinse well before cooking; a short soak shortens cooking time.', '1 kg', 19000, 16500, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Cajanus_cajan_Blanco1.167-cropped.jpg/500px-Cajanus_cajan_Blanco1.167-cropped.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['arhar dal', 'tuvar dal', 'pigeon pea', 'dal']::text[], true::boolean, true, 'Photo: Francisco Manuel Blanco (O.S.A.), Public domain, via Wikimedia Commons'),
  ('dairy-bread-eggs-milk', null, 'Toned Milk', 'toned-milk', 'Pasteurised toned milk for tea, coffee and cooking. Keep refrigerated and use before the date on the pouch.', '500 ml', 2800, 2700, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Glass_of_Milk_%2833657535532%29.jpg/500px-Glass_of_Milk_%2833657535532%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['doodh', 'milk', 'toned milk pouch']::text[], true::boolean, true, 'Photo: NIAID, CC BY 2.0, via Wikimedia Commons'),
  ('dairy-bread-eggs-bread-pav', null, 'Brown Bread', 'brown-bread', 'Sliced brown bread for sandwiches and toast. Store in a cool, dry place and consume within a few days of opening.', '400 g', 5000, 4500, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/Kommissbrot.jpg/500px-Kommissbrot.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['bread', 'sandwich bread', 'atta bread']::text[], true::boolean, true, 'Photo: Benutzer:Rainer Zenz, CC BY-SA 3.0, via Wikimedia Commons'),
  ('vegetables-fruits-fresh-vegetables', null, 'Potato', 'potato-1kg', 'Everyday potatoes for sabzi, curries, parathas and fries. Store in a cool, dark, airy place, away from onions.', '1 kg', 5000, 3900, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Patates.jpg/500px-Patates.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['aloo', 'alu', 'potato', 'batata']::text[], true::boolean, true, 'Photo: Scott Bauer, USDA ARS, Public domain, via Wikimedia Commons'),
  ('vegetables-fruits-fresh-vegetables', null, 'Baby Potato', 'baby-potato-500g', 'Small, thin-skinned potatoes that cook whole for dum aloo, roasts and stir-fries. Keep in a cool, dry place and use within a week.', '500 g', 4500, 3500, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Patates.jpg/500px-Patates.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['baby aloo', 'chhote aloo', 'small potato', 'dum aloo']::text[], true::boolean, true, 'Photo: Scott Bauer, USDA ARS, Public domain, via Wikimedia Commons'),
  ('vegetables-fruits-fresh-vegetables', null, 'Red Potato', 'red-potato-1kg', 'Red-skinned potatoes with firm flesh that holds its shape in curries, salads and roasts. Store cool and dark; do not refrigerate.', '1 kg', 7000, 5500, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Patates.jpg/500px-Patates.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['red aloo', 'lal aloo', 'red potato', 'potato']::text[], true::boolean, true, 'Photo: Scott Bauer, USDA ARS, Public domain, via Wikimedia Commons'),
  ('vegetables-fruits-fresh-vegetables', null, 'Onion', 'onion-1kg', 'Red onions for tadka, gravies, salads and raita. Keep in a dry, ventilated basket and away from potatoes to stop sprouting.', '1 kg', 6000, 4500, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Mixed_onions.jpg/500px-Mixed_onions.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['pyaz', 'pyaaz', 'kanda', 'onion', 'red onion']::text[], true::boolean, true, 'Photo: Colin, CC BY-SA 3.0, via Wikimedia Commons'),
  ('vegetables-fruits-fresh-vegetables', null, 'White Onion', 'white-onion-500g', 'Mild white onions that suit salads, soups and light gravies. Store in a dry, airy spot out of direct sunlight.', '500 g', 4500, 3500, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Mixed_onions.jpg/500px-Mixed_onions.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['safed pyaz', 'white onion', 'pyaaz', 'kanda']::text[], true::boolean, true, 'Photo: Colin, CC BY-SA 3.0, via Wikimedia Commons'),
  ('vegetables-fruits-fresh-vegetables', null, 'Sambar Onion', 'sambar-onion-500g', 'Small sambar onions with a sweet, sharp flavour for sambar, kuzhambu and pickles. Store dry and loose; peel just before use.', '500 g', 7000, 5500, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Shallots_-_sliced_and_whole.jpg/500px-Shallots_-_sliced_and_whole.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['small onion', 'chinna vengayam', 'shallots', 'sambar onion']::text[], true::boolean, true, 'Photo: No machine-readable author provided. Charles P. assumed (based on copyright clai, Public domain, via Wikimedia Commons'),
