  ('vegetables-fruits-frozen-veg', 'Sumeru', 'Sumeru Frozen Cut Beans', 'sumeru-frozen-cut-beans-500g', 'Frozen cut beans for stir-fries, soups and sabzi. Store frozen; do not refreeze after thawing.', '500 g', 12500, 11500, 5, '{}'::text[], array['frozen beans', 'french beans', 'cut beans', 'frozen sabzi']::text[], true::boolean, true, null),
  ('vegetables-fruits-frozen-veg', 'Sumeru', 'Sumeru Frozen Spinach', 'sumeru-frozen-spinach-500g', 'Frozen spinach for palak paneer, dal palak and soups. Thaw or cook from frozen and keep the pack at -18 C.', '500 g', 12000, 10900, 5, '{}'::text[], array['frozen palak', 'frozen spinach', 'palak', 'spinach']::text[], true::boolean, true, null),
  ('vegetables-fruits-frozen-veg', 'Safal', 'Safal Frozen Spinach', 'safal-frozen-spinach-500g', 'Frozen spinach for quick palak dishes, parathas and soups. Use from frozen and reseal the pack after use.', '500 g', 11500, 10500, 5, '{}'::text[], array['frozen palak', 'frozen spinach', 'palak', 'spinach']::text[], true::boolean, true, null),
  ('atta-rice-dal-atta', 'Aashirvaad', 'Aashirvaad Whole Wheat Atta', 'aashirvaad-whole-wheat-atta-5kg', 'Whole wheat flour for soft everyday rotis and parathas. Transfer to an airtight container once opened and keep in a cool, dry place.', '5 kg', 31000, 28900, 5, array['https://images.openfoodfacts.org/images/products/890/172/512/1143/front_en.11.400.400.jpg']::text[], array['atta', 'wheat flour', 'gehu atta', 'chapati flour']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-atta', 'Pillsbury', 'Pillsbury Whole Wheat Atta', 'pillsbury-whole-wheat-atta-5kg', 'Chakki-ground whole wheat flour for rotis, phulkas and puris. Knead with lukewarm water for softer dough and store sealed away from moisture.', '5 kg', 29500, 27500, 5, '{}'::text[], array['atta', 'wheat flour', 'chakki atta', 'roti flour']::text[], true::boolean, true, null),
  ('atta-rice-dal-atta', 'Aashirvaad', 'Aashirvaad Sharbati Atta', 'aashirvaad-sharbati-atta-5kg', 'Atta milled from sharbati wheat, a grain variety grown mainly in Madhya Pradesh, used for rotis and parathas. Keep the pack sealed and dry.', '5 kg', 36000, 33500, 5, array['https://images.openfoodfacts.org/images/products/890/172/500/7911/front_en.3.400.400.jpg']::text[], array['sharbati atta', 'wheat flour', 'gehu atta', 'premium atta']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-atta', 'Pillsbury', 'Pillsbury Specialty Wheat Flour', 'pillsbury-specialty-wheat-flour-5kg', 'Specialty-grade wheat flour for everyday rotis and parathas. Sift before kneading if you like, and store in an airtight tin after opening.', '5 kg', 34000, 31500, 5, array['https://images.openfoodfacts.org/images/products/005/150/028/1420/front_en.3.400.400.jpg']::text[], array['wheat flour', 'atta', 'specialty atta', 'chapati flour']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-atta', 'Aashirvaad', 'Aashirvaad Multigrain Atta', 'aashirvaad-multigrain-atta-5kg', 'Wheat flour blended with other grains and millets for rotis with a slightly nutty taste. Store in a cool, dry place and use within the date on the pack.', '5 kg', 39500, 36900, 5, '{}'::text[], array['multigrain atta', 'mixed flour', 'atta', 'millet flour']::text[], true::boolean, true, null)
) as v(cat, brand, name, slug, description, unit_label, mrp, price, tax_rate, images, tags, is_veg, orderable, image_credit)
join public.categories c on c.slug = v.cat
left join public.brands b on b.name = v.brand;

insert into public.products (category_id, brand_id, name, slug, description, unit_label, mrp, price, tax_rate, images, tags, is_veg, orderable, image_credit)
select c.id, b.id, v.name, v.slug, v.description, v.unit_label, v.mrp, v.price, v.tax_rate, v.images, v.tags, v.is_veg, v.orderable, v.image_credit from (values
  ('atta-rice-dal-atta', 'Pillsbury', 'Pillsbury Multigrain Atta', 'pillsbury-multigrain-atta-5kg', 'A wheat and millet flour mix for rotis, theplas and parathas. The dough may need a little more water than plain atta; keep the pack tightly closed.', '5 kg', 37000, 34500, 5, '{}'::text[], array['multigrain atta', 'atta', 'mixed grain flour', 'roti flour']::text[], true::boolean, true, null),
  ('atta-rice-dal-local-rice', 'Daawat', 'Daawat Sona Masoori Rice', 'daawat-sona-masoori-rice-5kg', 'Light, medium-grain Sona Masoori rice suited to daily meals, pongal and lemon rice. Rinse before cooking and store in a covered container.', '5 kg', 52000, 47900, 5, array['https://images.openfoodfacts.org/images/products/890/153/707/4415/front_en.3.400.400.jpg']::text[], array['sona masoori', 'chawal', 'rice', 'south indian rice']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-local-rice', 'Fortune', 'Fortune Sona Masoori Rice', 'fortune-sona-masoori-rice-5kg', 'Medium-grain Sona Masoori rice that cooks soft and separate for everyday rice with sambar or rasam. Keep dry and away from pantry pests.', '5 kg', 49500, 45900, 5, array['https://images.openfoodfacts.org/images/products/890/600/728/9238/front_en.3.400.400.jpg']::text[], array['sona masoori', 'chawal', 'rice', 'daily rice']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-local-rice', null, 'HMT Rice', 'hmt-rice-1kg', 'Loose raw HMT rice, a fine short-grain variety popular in central and south India for daily meals. Wash well before cooking and store in a sealed bin.', '1 kg', 7500, 6500, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/20201102.Hengnan.Hybrid_rice_Sanyou-1.6.jpg/500px-20201102.Hengnan.Hybrid_rice_Sanyou-1.6.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['hmt rice', 'chawal', 'raw rice', 'loose rice']::text[], true::boolean, true, 'Photo: China News Service, CC BY 3.0, via Wikimedia Commons'),
  ('atta-rice-dal-local-rice', null, 'HMT Steam Rice', 'hmt-steam-rice-1kg', 'Steam-processed HMT rice that keeps grains firm and separate after cooking. Good for plain rice, khichdi and fried rice; store dry in a closed container.', '1 kg', 8000, 6900, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/20201102.Hengnan.Hybrid_rice_Sanyou-1.6.jpg/500px-20201102.Hengnan.Hybrid_rice_Sanyou-1.6.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['hmt steam rice', 'chawal', 'steam rice', 'loose rice']::text[], true::boolean, true, 'Photo: China News Service, CC BY 3.0, via Wikimedia Commons'),
  ('atta-rice-dal-local-rice', 'bb Royal', 'bb Royal Kolam Rice', 'bb-royal-kolam-rice-5kg', 'Short, slender kolam rice that cooks soft, a staple in Maharashtra and Gujarat for dal-chawal. Rinse two or three times and store in an airtight bin.', '5 kg', 44000, 39900, 5, '{}'::text[], array['kolam rice', 'surti kolam', 'chawal', 'rice']::text[], true::boolean, true, null),
  ('atta-rice-dal-local-rice', 'Double Horse', 'Double Horse Ponni Rice', 'double-horse-ponni-rice-5kg', 'Ponni rice from Tamil Nadu, a medium-grain variety used for daily meals, curd rice and variety rice. Store in a cool, dry place after opening.', '5 kg', 42000, 38900, 5, array['https://images.openfoodfacts.org/images/products/890/401/150/3821/front_en.3.400.400.jpg']::text[], array['ponni rice', 'chawal', 'south indian rice', 'rice']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-local-rice', null, 'Telangana Fine Rice', 'telangana-fine-rice-1kg', 'Loose fine-grain white rice from Telangana mills for everyday cooking. Soak for 15 minutes before cooking for even grains and keep in a sealed container.', '1 kg', 7000, 6200, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/20201102.Hengnan.Hybrid_rice_Sanyou-1.6.jpg/500px-20201102.Hengnan.Hybrid_rice_Sanyou-1.6.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['fine rice', 'chawal', 'telangana rice', 'loose rice']::text[], true::boolean, true, 'Photo: China News Service, CC BY 3.0, via Wikimedia Commons'),
  ('atta-rice-dal-local-rice', null, 'White Rice', 'white-rice-1kg', 'Graded loose white rice for daily use with dal, curry and sambar. Rinse until the water runs clear and store away from moisture.', '1 kg', 5800, 5200, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Half_a_cup_of_rice._Brown_rice_is_the_best_choice.JPG/500px-Half_a_cup_of_rice._Brown_rice_is_the_best_choice.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['white rice', 'chawal', 'loose rice', 'daily rice']::text[], true::boolean, true, 'Photo: Hannahdownes, CC BY-SA 4.0, via Wikimedia Commons'),
  ('atta-rice-dal-rice', 'India Gate', 'India Gate Basmati Rice', 'india-gate-basmati-rice-1kg', 'Long-grain aged basmati rice with a natural aroma, suited to pulao, biryani and jeera rice. Soak for 20-30 minutes before cooking.', '1 kg', 22000, 19900, 5, array['https://images.openfoodfacts.org/images/products/069/022/510/1134/front_en.16.400.400.jpg']::text[], array['basmati', 'basmati chawal', 'long grain rice', 'biryani rice']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-rice', 'Daawat', 'Daawat Basmati Rice', 'daawat-basmati-rice-1kg', 'Fragrant long-grain basmati rice for biryani, pulao and everyday steamed rice. Rinse gently to keep the grains intact and store in an airtight jar.', '1 kg', 21000, 18900, 5, array['https://images.openfoodfacts.org/images/products/490/113/502/5127/front_en.3.400.400.jpg']::text[], array['basmati', 'basmati chawal', 'rice', 'pulao rice']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-rice', 'India Gate', 'India Gate Brown Rice', 'india-gate-brown-rice-1kg', 'Brown basmati rice with the bran layer intact, giving a chewier bite. Soak for at least 30 minutes and cook with a little extra water.', '1 kg', 23000, 20900, 5, array['https://images.openfoodfacts.org/images/products/069/022/510/6542/front_en.7.400.400.jpg']::text[], array['brown rice', 'brown basmati', 'unpolished rice', 'chawal']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-rice', 'Daawat', 'Daawat Brown Rice', 'daawat-brown-rice-1kg', 'Whole-grain brown basmati rice for pulao, rice bowls and salads. Takes longer to cook than white rice; keep sealed in a cool place.', '1 kg', 22500, 20500, 5, array['https://images.openfoodfacts.org/images/products/890/153/707/4354/front_en.20.400.400.jpg']::text[], array['brown rice', 'brown basmati', 'whole grain rice', 'chawal']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-rice', 'Double Horse', 'Double Horse Idli Rice', 'double-horse-idli-rice-5kg', 'Parboiled short-grain rice for grinding idli and dosa batter with urad dal. Soak four to six hours before grinding and store the pack dry.', '5 kg', 38000, 34900, 5, '{}'::text[], array['idli rice', 'dosa rice', 'parboiled rice', 'boiled rice']::text[], true::boolean, true, null),
  ('atta-rice-dal-rice', 'bb Royal', 'bb Royal Idli Rice', 'bb-royal-idli-rice-5kg', 'Idli rice for soft, fluffy idlis and crisp dosas. Combine roughly four parts rice to one part urad dal, soak and grind; keep the rest airtight.', '5 kg', 36000, 32900, 5, '{}'::text[], array['idli rice', 'dosa rice', 'idli chawal', 'batter rice']::text[], true::boolean, true, null),
  ('atta-rice-dal-rice', '24 Mantra Organic', '24 Mantra Organic Red Rice', '24-mantra-organic-red-rice-1kg', 'Organic red rice with a reddish bran and earthy flavour, eaten with curries in Kerala and coastal Karnataka. Soak before cooking; cooks a little firmer.', '1 kg', 16000, 14500, 5, '{}'::text[], array['red rice', 'matta rice', 'organic rice', 'lal chawal']::text[], true::boolean, true, null),
  ('atta-rice-dal-rice', 'Organic Tattva', 'Organic Tattva Black Rice', 'organic-tattva-black-rice-500g', 'Organic black rice that turns deep purple when cooked, used for kheer, salads and rice bowls. Soak for a few hours and store in an airtight jar.', '500 g', 19000, 17200, 5, '{}'::text[], array['black rice', 'kala chawal', 'forbidden rice', 'organic rice']::text[], true::boolean, true, null),
  ('atta-rice-dal-dal', 'Tata Sampann', 'Tata Sampann Toor Dal', 'tata-sampann-toor-dal-1kg', 'Unpolished split pigeon peas for everyday dal, sambar and dal fry. Rinse and pressure-cook until soft; store in a dry, airtight container.', '1 kg', 21000, 18900, 5, array['https://images.openfoodfacts.org/images/products/890/404/392/6216/front_en.5.400.400.jpg']::text[], array['toor dal', 'arhar dal', 'tuvar dal', 'pigeon pea']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-dal', 'Fortune', 'Fortune Toor Dal', 'fortune-toor-dal-1kg', 'Split pigeon peas that cook to a creamy dal for rice and rotis. Soak for 20 minutes to shorten cooking time and keep the pack sealed.', '1 kg', 19500, 17900, 5, array['https://images.openfoodfacts.org/images/products/890/600/881/5153/front_en.3.400.400.jpg']::text[], array['toor dal', 'arhar dal', 'tuvar dal', 'dal']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-dal', 'Tata Sampann', 'Tata Sampann Moong Dal', 'tata-sampann-moong-dal-1kg', 'Split yellow moong lentils that cook quickly for dal, khichdi and halwa. No long soaking needed; store in a cool, dry place.', '1 kg', 18000, 16500, 5, array['https://images.openfoodfacts.org/images/products/890/404/392/6315/front_en.23.400.400.jpg']::text[], array['moong dal', 'yellow moong', 'mung dal', 'dal']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-dal', 'Fortune', 'Fortune Moong Dal', 'fortune-moong-dal-1kg', 'Split moong dal for light everyday dal, khichdi and cheela batter. Rinse well before use and keep in an airtight jar after opening.', '1 kg', 17000, 15500, 5, '{}'::text[], array['moong dal', 'mung dal', 'yellow dal', 'khichdi dal']::text[], true::boolean, true, null),
  ('atta-rice-dal-dal', 'Tata Sampann', 'Tata Sampann Masoor Dal', 'tata-sampann-masoor-dal-1kg', 'Split red lentils that turn golden and soft within minutes, ideal for quick dal and soups. Store away from moisture in a closed container.', '1 kg', 15000, 13800, 5, '{}'::text[], array['masoor dal', 'red lentil', 'malka masoor', 'dal']::text[], true::boolean, true, null),
  ('atta-rice-dal-dal', 'Fortune', 'Fortune Masoor Dal', 'fortune-masoor-dal-1kg', 'Red split lentils for everyday dal tadka, soups and Bengali-style masoor dal. Cooks without soaking; keep the pack tightly closed.', '1 kg', 14000, 12900, 5, '{}'::text[], array['masoor dal', 'red lentil', 'lal masoor', 'dal']::text[], true::boolean, true, null),
  ('atta-rice-dal-dal', 'Tata Sampann', 'Tata Sampann Urad Dal', 'tata-sampann-urad-dal-1kg', 'Split white urad dal for idli and dosa batter, vadas and tempering. Soak before grinding and store in an airtight container.', '1 kg', 19000, 17200, 5, array['https://images.openfoodfacts.org/images/products/890/404/392/6124/front_en.3.400.400.jpg']::text[], array['urad dal', 'white urad', 'ulundu', 'black gram']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-dal', 'Fortune', 'Fortune Urad Dal', 'fortune-urad-dal-1kg', 'Urad dal for batters, medu vada and dal makhani-style dishes. Rinse well, soak as the recipe needs and keep the rest dry and sealed.', '1 kg', 18000, 16500, 5, '{}'::text[], array['urad dal', 'black gram', 'ulundu', 'dal']::text[], true::boolean, true, null),
  ('atta-rice-dal-dal', 'Tata Sampann', 'Tata Sampann Chana Dal', 'tata-sampann-chana-dal-1kg', 'Split Bengal gram for chana dal, dal vada and sweets like puran poli. Soak for an hour to cut cooking time; store dry.', '1 kg', 13000, 11900, 5, array['https://images.openfoodfacts.org/images/products/890/404/392/6643/front_en.3.400.400.jpg']::text[], array['chana dal', 'bengal gram', 'split chickpea', 'dal']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-dal', 'Fortune', 'Fortune Chana Dal', 'fortune-chana-dal-1kg', 'Split Bengal gram for thick dals, kootu and tempering in South Indian cooking. Keep in an airtight jar away from humidity.', '1 kg', 12500, 11500, 5, array['https://images.openfoodfacts.org/images/products/890/600/728/6039/front_en.3.400.400.jpg']::text[], array['chana dal', 'bengal gram', 'kadalai paruppu', 'dal']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-dal', null, 'Horse Gram', 'horse-gram-500g', 'Loose whole horse gram (kulthi), a hardy pulse used in rasam, soups and sprouts in South India. Soak overnight before pressure-cooking.', '500 g', 7000, 6200, 0, '{}'::text[], array['horse gram', 'kulthi', 'kollu', 'hurali']::text[], true::boolean, true, null),
  ('atta-rice-dal-dal', null, 'Cowpea', 'cowpea-500g', 'Loose whole cowpeas for curries, usal and salads. Soak for six to eight hours, then pressure-cook until tender; store in a dry jar.', '500 g', 8000, 7200, 0, array['https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Lobia.jpg/500px-Lobia.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail']::text[], array['cowpea', 'chawli', 'lobia', 'karamani']::text[], true::boolean, true, 'Photo: HeraldDesa at English Wikipedia, CC BY-SA 3.0, via Wikimedia Commons'),
  ('atta-rice-dal-dal', null, 'Moth Beans', 'moth-beans-500g', 'Small brown moth beans (matki) for sprouting, misal and dry sabzi. Soak overnight and keep sprouts refrigerated for up to two days.', '500 g', 8500, 7600, 0, array['https://upload.wikimedia.org/wikipedia/commons/2/2f/Matki.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled']::text[], array['moth beans', 'matki', 'math dal', 'sprouting beans']::text[], true::boolean, true, 'Photo: Lalitstar at English Wikipedia, CC BY-SA 3.0, via Wikimedia Commons'),
  ('atta-rice-dal-besan-sooji-maida', 'Fortune', 'Fortune Besan', 'fortune-besan-1kg', 'Fine gram flour for pakoras, kadhi, cheela and laddoos. Sift before use for a smooth batter and store in an airtight container.', '1 kg', 14000, 12800, 5, array['https://images.openfoodfacts.org/images/products/890/600/728/5025/front_en.7.400.400.jpg']::text[], array['besan', 'gram flour', 'chickpea flour', 'kadalai maavu']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-besan-sooji-maida', 'Aashirvaad', 'Aashirvaad Besan', 'aashirvaad-besan-1kg', 'Gram flour made from chana dal for bhajjis, dhokla, kadhi and sweets. Keep sealed and away from moisture to prevent lumps.', '1 kg', 15000, 13800, 5, '{}'::text[], array['besan', 'gram flour', 'chana atta', 'pakora flour']::text[], true::boolean, true, null),
  ('atta-rice-dal-besan-sooji-maida', 'Aashirvaad', 'Aashirvaad Sooji', 'aashirvaad-sooji-1kg', 'Wheat semolina for upma, rava idli, halwa and crisp coatings. Dry-roast before use for better flavour and keep in a closed jar.', '1 kg', 7500, 6900, 5, '{}'::text[], array['sooji', 'rava', 'semolina', 'suji']::text[], true::boolean, true, null),
  ('atta-rice-dal-besan-sooji-maida', 'Fortune', 'Fortune Sooji', 'fortune-sooji-500g', 'Semolina for upma, sheera, rava dosa and cakes. Store in an airtight container; roasting it lightly helps it keep longer.', '500 g', 4200, 3900, 5, '{}'::text[], array['sooji', 'rava', 'semolina', 'bombay rava']::text[], true::boolean, true, null),
  ('atta-rice-dal-besan-sooji-maida', 'Aashirvaad', 'Aashirvaad Maida', 'aashirvaad-maida-1kg', 'Refined wheat flour for naan, bhatura, samosa pastry and baking. Store in a dry, airtight container away from strong odours.', '1 kg', 6500, 5900, 5, '{}'::text[], array['maida', 'all purpose flour', 'refined flour', 'plain flour']::text[], true::boolean, true, null),
  ('atta-rice-dal-besan-sooji-maida', 'Fortune', 'Fortune Maida', 'fortune-maida-1kg', 'All-purpose refined flour for cakes, cookies, parathas and fried snacks. Sift before baking and keep the pack tightly sealed.', '1 kg', 6000, 5500, 5, array['https://images.openfoodfacts.org/images/products/890/600/881/1117/front_en.3.400.400.jpg']::text[], array['maida', 'all purpose flour', 'baking flour', 'refined flour']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
  ('atta-rice-dal-besan-sooji-maida', 'Double Horse', 'Double Horse Rice Flour', 'double-horse-rice-flour-1kg', 'Fine rice flour for appam, idiyappam, pathiri and crisp murukku. Store in an airtight jar and use within the date on the pack.', '1 kg', 8500, 7800, 5, '{}'::text[], array['rice flour', 'chawal ka atta', 'arisi maavu', 'pathiri podi']::text[], true::boolean, true, null),
  ('atta-rice-dal-besan-sooji-maida', 'MTR', 'MTR Rice Flour', 'mtr-rice-flour-500g', 'Rice flour for akki roti, murukku, dosa batter and as a crisp coating for fries. Keep dry and sealed after opening.', '500 g', 5500, 5000, 5, '{}'::text[], array['rice flour', 'chawal atta', 'akki hittu', 'gluten free flour']::text[], true::boolean, true, null),
  ('atta-rice-dal-besan-sooji-maida', 'Weikfield', 'Weikfield Corn Flour', 'weikfield-corn-flour-500g', 'Corn starch for thickening soups and gravies and for crisp coatings on Indo-Chinese starters. Mix with cold water before adding to hot liquids.', '500 g', 8500, 7800, 12, '{}'::text[], array['corn flour', 'corn starch', 'cornflour', 'makai starch']::text[], true::boolean, true, null),
