  ('dairy-bread-eggs-batter', 'iD Fresh', 'iD Fresh Ragi Dosa Batter', 'id-fresh-ragi-dosa-batter-1kg', 'Fermented batter made with ragi for dosas and idlis with an earthy flavour. Keep refrigerated and use before the date on pack.', '1 kg', 11000, 10400, 5, '{}'::text[], array['ragi batter', 'ragi dosa', 'millet batter', 'nachni dosa']::text[], true::boolean, true, null),
  ('dairy-bread-eggs-paneer-tofu', 'Amul', 'Amul Paneer', 'amul-paneer-200g', 'Fresh paneer block for paneer butter masala, tikka and bhurji. Soak in warm water for softer texture; keep refrigerated.', '200 g', 9500, 9000, 5, array['https://images.openfoodfacts.org/images/products/890/126/218/0146/front_en.3.400.400.jpg']::text[], array['paneer', 'cottage cheese', 'chhena', 'paneer block']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA')
) as v(cat, brand, name, slug, description, unit_label, mrp, price, tax_rate, images, tags, is_veg, orderable, image_credit)
join public.categories c on c.slug = v.cat
left join public.brands b on b.name = v.brand;

