  ('dairy-bread-eggs-paneer-tofu', 'Milky Mist', 'Milky Mist Paneer', 'milky-mist-paneer-200g', 'Soft paneer for curries, grilled tikka and stuffed parathas. Store chilled and use within two days of opening.', '200 g', 10000, 9400, 5, array['https://images.openfoodfacts.org/images/products/890/408/330/0021/front_en.10.400.400.jpg']::text[], array['paneer', 'cottage cheese', 'fresh paneer', 'malai paneer']::text[], true::boolean, true, 'Photo: Open Food Facts contributors, CC BY-SA'),
