  ('hair-hair-accessories', 'Miniso', 'Miniso Hair Scrunchies', 'miniso-hair-scrunchies-pack-of-3', 'Set of fabric scrunchies for tying ponytails and buns. Keep a spare on your wrist or in your bag.', 'Pack of 3', 19900, 18900, 18, '{}'::text[], array['scrunchies', 'hair ties', 'rubber band', 'hair band']::text[], null::boolean, true, null),
